begin;select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000001051','mfa-admin@example.test'),('00000000-0000-4000-8000-000000001052','mfa-staff@example.test');
update public.profiles set role='admin' where id='00000000-0000-4000-8000-000000001051';update public.profiles set role='staff' where id='00000000-0000-4000-8000-000000001052';
insert into public.brands(id,name) values('00000000-0000-4000-8000-000000001053','MFA fixture');
insert into public.brand_users(brand_id,user_id) values('00000000-0000-4000-8000-000000001053','00000000-0000-4000-8000-000000001051');
set local role authenticated;set local request.jwt.claim.sub='00000000-0000-4000-8000-000000001051';set local request.jwt.claims='{"aal":"aal1"}';
select is(app.current_role(),null,'admin role unavailable before MFA');
select is((select count(*) from public.profiles),1::bigint,'own profile can support enrollment');
select is((select count(*) from public.brands),0::bigint,'business read denied before MFA');
select is((select count(*) from public.brand_users),0::bigint,'own membership does not bypass mandatory MFA');
select throws_ok($$select public.start_import_batch(gen_random_uuid(),'budgets','mfa.csv',repeat('f',64),10)$$,'42501','FORBIDDEN','business RPC denied before MFA');
select throws_ok($$insert into public.brands(name) values('Blocked MFA')$$,'42501',null,'business write denied before MFA');
select lives_ok($$select public.revoke_push_subscription()$$,'own logout consent revocation remains possible');
set local request.jwt.claims='{"aal":"aal2"}';
select is(app.current_role(),'admin'::public.app_role,'verified admin role restored');
select is((select count(*) from public.brands where id='00000000-0000-4000-8000-000000001053'),1::bigint,'verified admin reads permitted business');
set local request.jwt.claims='{"aal":"aal1"}';set local request.jwt.claim.sub='00000000-0000-4000-8000-000000001052';
select is(app.current_role(),'staff'::public.app_role,'staff keeps original authorization');
select is((select count(*) from public.brands where id='00000000-0000-4000-8000-000000001053'),1::bigint,'staff read unaffected');
reset role;
select ok(not exists(select 1 from pg_tables t where schemaname='public' and tablename<>'profiles' and not exists(select 1 from pg_policies p where p.schemaname=t.schemaname and p.tablename=t.tablename and p.policyname='admin_mfa_required' and p.permissive='RESTRICTIVE')),'all business tables have restrictive MFA gate');
select * from finish();rollback;
